 <section class="paper-card"><h2>النتائج</h2><div class="card-body" id="catalogResults">${demoBooks.map(b=>`<article class="book-card"><div class="book-cover">📚</div><div><h3>${b.title}</h3><p>${b.author}</p><p>${b.meta}</p><span class="chip">${b.kind}</span><div class="book-actions"><button class="btn secondary" data-action="book-detail">تفاصيل الفهرسة</button><button class="btn ghost" data-action="rights-info">حالة الإتاحة والحقوق</button></div></div></article>`).join('')}</div></section>
