function renderStudy(){return `<div class="page-shell"><div class="notice-strip">الملاحظات والاقتباسات خاصة افتراضياً. في وضع الواجهة الثابتة تُحفظ محلياً على هذا الجهاز؛ بعد إعداد API يمكن مزامنتها بحساب المستخدم.</div><div class="grid-3"><div class="tool-tile"><b>📖 دفتر المطالعة</b><p>تدوين الفوائد ومتابعة آخر موضع قراءة.</p><button class="btn secondary" data-action="open-notes">فتح الدفتر</button></div><div class="tool-tile"><b>🔬 دفتر التحقيق</b><p>مقارنة النسخ وإثبات الفروق ومصادر النصوص.</p><button class="btn secondary" data-action="open-investigation">فتح دفتر التحقيق</button></div><div class="tool-tile"><b>🧷 الاقتباسات والحواشي</b><p>حفظ النص مع الجزء والصفحة والطبعة.</p><button class="btn secondary" data-action="open-citations">إدارة الاقتباسات</button></div><div class="tool-tile"><b>📚 خطة القراءة</b><p>تنظيم الكتب والدروس حسب التخصص.</p><button class="btn secondary" data-action="reading-plan">إنشاء خطة</button></div><div class="tool-tile"><b>🧠 المصطلحات العلمية</b><p>حفظ تعريفاتك ومراجعتها ضمن الملاحظات.</p><button class="btn secondary" data-action="terms">بطاقات المصطلحات</button></div><div class="tool-tile"><b>📝 تصدير البحث</b><p>تجهيز المحتوى لاحقاً بصيغ Word وPDF.</p><button class="btn secondary" data-action="export-info">خيارات التصدير</button></div></div><section class="paper-card" id="studyWorkspace"><h2>دفتر الملاحظات والاقتباسات</h2><div class="card-body"><form id="noteForm"><div class="form-row"><div class="field"><label for="noteKind">نوع السجل</label><select id="noteKind"><option value="note">ملاحظة</option><option value="quote">اقتباس</option><option value="citation">إحالة مصدرية</option><option value="research">مادة بحثية / تحقيق</option></select></div><div class="field"><label for="noteTitle">العنوان</label><input id="noteTitle" required placeholder="عنوان الفائدة أو الاقتباس"></div></div><div class="field"><label for="noteBody">النص أو بيانات الإحالة</label><textarea id="noteBody" required placeholder="النص المنقول أو الملاحظة العلمية"></textarea></div><div class="field"><label for="noteLocator">المصدر والطبعة والجزء والصفحة / الموضع</label><input id="noteLocator" placeholder="اسم الكتاب، الطبعة، ج 1، ص 25"></div><button class="btn" type="submit">حفظ في دفتر هذا الجهاز</button></form><div id="savedNotes" class="notice-strip">لا توجد ملاحظات محفوظة.</div></div></section></div>`}
