function renderGroups(){return `<div class="page-shell"><div class="notice-strip">كل مجموعة أو قناة تمر بمراجعة المالك قبل النشر والترقية. نقاط الجودة العلمية والأنشطة المعتمدة أعلى وزناً من كثرة الرسائل، ويُمنع التفاعل الوهمي.</div><div class="grid-3">${stat('المستويات','10','لا توجد مستويات بعد العاشر')}${stat('اعتماد الترقية','يدوي','لا يُمنح الوسام تلقائياً')}${stat('مراجعة المالك','إلزامية','لإنشاء المجموعات والقنوات المميزة')}</div><section class="paper-card"><h2>سلم مستويات المجموعات والقنوات</h2><div class="card-body"><div class="level-list">${levels.map((p,i)=>`<div class="level"><span>المستوى ${i+1}</span><b>${p.toLocaleString('en-US')}</b><small>نقطة للترقية</small><div class="progress"><i></i></div><small>${['وسام البداية','وسام النشاط','وسام التفاعل','وسام التميز','وسام النخبة','وسام الريادة','وسام الاحتراف','وسام الإبداع','وسام السيادة','وسام القيّوم'][i]}</small></div>`).join('')}</div></div></section><section class="paper-card"><h2>احتساب النقاط</h2><div class="card-body"><div class="grid-2"><div class="tool-tile"><b>40% البحوث والمحتوى العلمي</b><p>بحث موثق ومفيد ومراجَع علمياً.</p></div><div class="tool-tile"><b>30% الفعاليات والمبادرات</b><p>المسابقات والفعاليات العلمية والثقافية.</p></div><div class="tool-tile"><b>20% التفاعل الحقيقي</b><p>المناقشات المفيدة والتفاعل غير المصطنع.</p></div><div class="tool-tile"><b>10% نمو الأعضاء</b><p>الأعضاء الحقيقيون واستمرار النشاط.</p></div></div><p class="muted">كل نقطة لها سجل يوضح مصدرها ومراجعها، وتُخصم النقاط المخالفة بعد المراجعة وإثبات التلاعب.</p></div></section></div>`}
function renderAssistant(){return `<div class="page-shell"><div class="notice-strip warning">المساعد العلمي غير متصل بنموذج ذكاء اصطناعي أو فهرس مصادر في هذه النسخة. لن تُعرض إجابات أو مراجع مختلقة.</div><section class="paper-card"><h2>إعداد نطاق المصادر</h2><div class="card-body"><form id="assistantForm"><div class="field"><label>مصادر الإجابة</label><select id="assistantScope" required><option value="">اختر نطاق المصادر قبل المتابعة</option><option value="library">مصادر مكتبة القيّوم الموثقة فقط</option><option value="external">مصادر المكتبة والمصادر الخارجية مع تمييزها</option></select></div><div class="field"><label>سؤالك العلمي</label><textarea id="assistantQuestion" required placeholder="اكتب المسألة أو السؤال العلمي"></textarea></div><button class="btn" type="submit">إعداد السؤال (غير متصل)</button></form></div></section><div class="grid-3"><div class="tool-tile"><b>📚 توثيق المصادر</b><p>اسم المصدر والطبعة والجزء والصفحة.</p></div><div class="tool-tile"><b>⚖️ فصل المنقول عن التحليل</b><p>تمييز النص الأصلي عن الشرح والاستنتاج.</p></div><div class="tool-tile"><b>🔍 درجة التحقق</b><p>بيان ما ثبت وما يحتاج مراجعة علمية.</p></div></div></div>`}
function renderReader(){return `<div class="page-shell"><div class="notice-strip warning">القارئ المحلي يفتح الملفات التي تختارها من جهازك فقط. رفع نسخة إلى الخادم لا يجعلها متاحة؛ يلزم فحص تقني ومراجعة حقوق وموافقة نشر مستقلة.</div><section class="paper-card"><h2>فتح كتاب من جهازك</h2><div class="card-body"><div class="field"><label for="readerFile">ملف PDF أو EPUB</label><input id="readerFile" type="file" accept="application/pdf,.pdf,application/epub+zip,.epub"></div><p class="muted">لا يُرفع الملف تلقائياً ولا يغادر جهازك عند استخدام القارئ المحلي.</p><div class="toolbar"><button class="btn secondary" data-action="reader-zoom-in">تكبير +</button><button class="btn secondary" data-action="reader-zoom-out">تصغير −</button><button class="btn secondary" data-action="reader-night">الوضع الليلي</button><button class="btn secondary" data-action="reader-bookmark">إضافة علامة</button><button class="btn secondary" data-action="reader-note">ملاحظة على الموضع</button></div><div class="field" style="max-width:220px;margin-top:12px"><label>رقم الصفحة / الموضع</label><input type="number" min="1" value="1" id="readerPage"></div><div id="readerStatus" class="muted" aria-live="polite">لم يتم اختيار ملف.</div><button class="btn" type="button" data-action="reader-upload">إرسال نسخة إلى حجر المراجعة (يتطلب الدخول)</button></div></section><div class="paper-card" id="readerCanvas"><h2>منطقة القراءة</h2><div class="card-body" id="readerContent"><div class="empty-state">اختر ملف PDF أو EPUB من جهازك لبدء القراءة.</div></div></div><section class="paper-card"><h2>علاماتك وملاحظات القراءة</h2><div class="card-body" id="readerSavedItems">${renderReaderSavedItems()}</div></section></div>`}
function renderReaderSavedItems(){const marks=readStore('qayyum-reader-bookmarks'),notes=readStore('qayyum-reader-notes');return [...marks.map(x=>({...x,type:'علامة'})),...notes.map(x=>({...x,type:'ملاحظة'}))].sort((a,b)=>b.at-a.at).slice(0,60).map(x=>`<article class="notice-strip"><b>${x.type} · ${escapeHtml(String(x.page||''))}</b><p>${escapeHtml(x.note||'موضع قراءة محفوظ')}</p><small>${new Date(x.at).toLocaleString('ar')}</small></article>`).join('')||'<div class="empty-state">لا توجد علامات أو ملاحظات بعد.</div>'}
function openLocalReader(file){const box=$('#readerContent'),status=$('#readerStatus');if(!file||!box)return;const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','epub'].includes(ext)){status.textContent='نوع الملف غير مدعوم.';return}if(window.readerObjectUrl)URL.revokeObjectURL(window.readerObjectUrl);window.readerObjectUrl=URL.createObjectURL(file);status.textContent=`${file.name} · ${(file.size/1048576).toFixed(2)} MB · قراءة محلية`;
 if(ext==='pdf')box.innerHTML=`<object data="${window.readerObjectUrl}" type="application/pdf" aria-label="قارئ PDF" style="width:100%;height:78vh"><p>تعذر عرض PDF داخل المتصفح. افتح الملف محلياً من جهازك.</p></object>`;
 else {box.innerHTML='<div id="epubReader" style="height:78vh;overflow:auto"></div>';if(!window.ePub){const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/epubjs/dist/epub.min.js';script.onload=()=>{if(window.ePub){window.activeEpub=window.ePub(window.readerObjectUrl);window.activeEpub.renderTo('epubReader',{width:'100%',height:'100%'}).display()}};document.head.append(script)}else{window.activeEpub=window.ePub(window.readerObjectUrl);window.activeEpub.renderTo('epubReader',{width:'100%',height:'100%'}).display()}}
 try{localStorage.setItem('qayyum-last-reader-file',file.name)}catch{}}

