function route(){const key=(location.hash||'#home').slice(1).split('?')[0];if(key==='sections'||key==='all-sections'){home.hidden=false;page.hidden=true;setTimeout(()=>$(key==='all-sections'?'#all-sections':'#sections')?.scrollIntoView({behavior:'smooth'}),0);return}renderPage(key);$$('#mainNav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${key}`));nav.classList.remove('open');menuToggle.setAttribute('aria-expanded','false')}
