const languageGrid=$('#languageGrid'), languageSearch=$('#languageSearch');
const googleLanguageCode={ckb:'ku',zgh:'tzm',zh:'zh-CN',he:'iw'};
const googleSupported=new Set('af sq am ar hy az eu be bn bs bg ca ceb zh-CN zh-TW co hr cs da nl en eo et tl fi fr fy gl ka de el gu ht ha haw iw hi hmn hu is ig id ga it ja jw kn kk km ko ku ky lo la lv lt lb mk mg ms ml mt mi mr mn my ne no ny ps fa pl pt pa ro ru sm gd sr st sn sd si sk sl so es su sw sv tg ta te th tr tk tt tzm uk ur uz vi cy xh yi yo zu'.split(' '));
function renderLanguageChoices(filter=''){
 const q=filter.trim().toLocaleLowerCase();
 const current=document.documentElement.lang||'ar';
 const shown=languages.filter(l=>`${l.name} ${l.native} ${l.code}`.toLocaleLowerCase().includes(q));
 languageGrid.innerHTML=shown.map(l=>`<button type="button" data-language="${l.code}" lang="${l.code}" dir="${l.direction}" class="${l.code===current?'selected':''}" aria-pressed="${l.code===current}"><strong>${l.name}</strong><small>${l.native}</small></button>`).join('')||'<p class="muted">لا توجد لغة مطابقة.</p>';
}
renderLanguageChoices();
languageSearch?.addEventListener('input',()=>renderLanguageChoices(languageSearch.value));
function setGoogleLanguage(code){
 if(code==='ar'){
   document.cookie='googtrans=/ar/ar;path=/';document.cookie='googtrans=/ar/ar;path=/;domain='+location.hostname;
   location.reload();return;
 }
 const target=googleLanguageCode[code]||code;
 if(!googleSupported.has(target))return false;
 const combo=document.querySelector('.goog-te-combo');
 if(combo){combo.value=target;combo.dispatchEvent(new Event('change'));return true;}
 return false;
}
function applyLanguage(lang,{translate=true,quiet=false}={}){
 document.documentElement.lang=lang.code;document.documentElement.dir=lang.direction;
 document.documentElement.dataset.language=lang.code;
 $('#currentLanguageLabel').textContent=lang.name;
 try{localStorage.setItem('qayyum-language',lang.code)}catch{}
 renderLanguageChoices(languageSearch?.value||'');
 if(translate){
   if(lang.code==='ar'){setGoogleLanguage('ar');return;}
   const ready=setGoogleLanguage(lang.code);
   $('#languageStatus').textContent=ready?'تم تطبيق اللغة المختارة. الترجمة آلية وتحتاج مراجعة للمصطلحات العلمية.':(googleSupported.has(googleLanguageCode[lang.code]||lang.code)?'جارٍ تحميل خدمة الترجمة؛ تأكد من الاتصال بالإنترنت إذا لم تتغير النصوص.':'هذه اللغة موجودة في القائمة، لكن خدمة الترجمة الآلية لا تدعمها حالياً؛ يلزم ملف ترجمة بشري مخصص.');
   if(!quiet)toast(ready?'تم تغيير لغة الواجهة. الترجمة آلية وقد تحتاج المصطلحات العلمية إلى مراجعة.':(googleSupported.has(googleLanguageCode[lang.code]||lang.code)?'تم حفظ اختيار اللغة؛ ستُطبّق الترجمة عند تحميل خدمة الترجمة.':'تم حفظ اختيار اللغة واتجاهها، لكن الترجمة الآلية غير متاحة لهذه اللغة حالياً.'));
 }
}
languageGrid.addEventListener('click',e=>{const b=e.target.closest('[data-language]');if(!b)return;const lang=languages.find(x=>x.code===b.dataset.language);if(!lang)return;applyLanguage(lang);$('#languageDialog').close();});
window.googleTranslateElementInit=function(){
 if(!window.google?.translate?.TranslateElement)return;
 new google.translate.TranslateElement({pageLanguage:'ar',includedLanguages:languages.filter(l=>l.code!=='ar').map(l=>googleLanguageCode[l.code]||l.code).filter((v,i,a)=>googleSupported.has(v)&&a.indexOf(v)===i).join(','),autoDisplay:false,multilingualPage:true},'google_translate_element');
 const saved=(()=>{try{return localStorage.getItem('qayyum-language')||'ar'}catch{return 'ar'}})();
 const lang=languages.find(x=>x.code===saved)||languages[0];
 if(saved!=='ar')setTimeout(()=>applyLanguage(lang,{quiet:true}),500);
};
(()=>{let saved='ar';try{saved=localStorage.getItem('qayyum-language')||'ar'}catch{}const lang=languages.find(x=>x.code===saved)||languages[0];document.documentElement.lang=lang.code;document.documentElement.dir=lang.direction;$('#currentLanguageLabel').textContent=lang.name;})();
function readStore(key){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return []}}
function writeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function loadLocalNotes(){const box=$('#savedNotes');if(!box)return;const notes=readStore('qayyum-notes');const labels={note:'ملاحظة',quote:'اقتباس',citation:'إحالة مصدرية',research:'مادة بحثية'};box.innerHTML=notes.length?notes.map(n=>`<article class="notice-strip"><b>${labels[n.kind]||'ملاحظة'} · ${escapeHtml(n.title)}</b><p>${escapeHtml(n.body)}</p><small>${escapeHtml(n.locator||'')} · ${new Date(n.at).toLocaleString('ar')}</small></article>`).join(''):'لا توجد ملاحظات محفوظة في هذا المتصفح.'}
function loadLocalProjects(){const box=$('#researchProjects');if(!box)return;const rows=readStore('qayyum-projects');box.innerHTML=rows.length?rows.map(p=>`<div class="notice-strip"><b>${escapeHtml(p.title)}</b><p>${escapeHtml(p.desc||'')}</p><small>مسودة محلية · ${new Date(p.at).toLocaleDateString('ar')}</small></div>`).join(''):'<div class="empty-state">لم تُنشأ مسودات بعد.</div>'}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.addEventListener('change',e=>{if(e.target.id==='readerFile')openLocalReader(e.target.files?.[0]);});
document.addEventListener('submit',async e=>{
 if(e.target.id==='catalogForm'){e.preventDefault();const q=$('#bookQuery')?.value.trim()||'';if(!API_BASE){$('#catalogResults').innerHTML='<div class="empty-state">واجهة العرض تعمل محلياً؛ اضبط API في وسم meta حتى تظهر سجلات قاعدة البيانات.</div>';return}try{const data=await apiRequest(`/api/catalog/works?q=${encodeURIComponent(q)}`);$('#catalogResults').innerHTML=data.items.length?data.items.map(w=>`<article class="book-card"><div class="book-cover">📚</div><div><h3>${escapeHtml(w.canonical_title)}</h3><p>${escapeHtml((w.authors||[]).join('، ')||'المؤلف غير محقق بعد')}</p><span class="chip">${escapeHtml(w.language_code||'')}</span> <span class="chip">${Number(w.edition_count||0)} طبعة معتمدة</span><div class="book-actions"><button class="btn secondary" data-action="book-detail" data-work-id="${escapeHtml(w.id)}">تفاصيل الكتاب</button></div></div></article>`).join(''):'<div class="empty-state">لا توجد نتائج منشورة مطابقة.</div>'}catch(err){toast(`تعذر البحث: ${err.message}`)}}
 if(e.target.id==='hadithForm'){e.preventDefault();$('#hadithResults').innerHTML='<div class="empty-state">تم استلام شروط البحث محلياً. ستظهر الروايات والأسانيد بعد ربط قاعدة البيانات.</div>';toast('تم تجهيز استعلام الروايات للربط.');}
 if(e.target.id==='researchForm'){e.preventDefault();const title=$('#researchTitle').value.trim();if(!title)return;const rows=readStore('qayyum-projects');rows.unshift({title,desc:$('#researchDesc').value,at:Date.now()});writeStore('qayyum-projects',rows);e.target.reset();loadLocalProjects();toast('حُفظت المسودة على هذا المتصفح.');}
 if(e.target.id==='noteForm'){e.preventDefault();const item={kind:$('#noteKind')?.value||'note',title:$('#noteTitle').value,body:$('#noteBody').value,locator:$('#noteLocator')?.value||'',at:Date.now()};if(API_BASE&&apiToken()){try{await apiRequest('/api/research/notes',{method:'POST',body:JSON.stringify({kind:item.kind,title:item.title,body:item.body,locator:item.locator})});toast('تم حفظ السجل الخاص في حسابك.')}catch(err){toast(`تعذر الحفظ على الخادم: ${err.message}`);return}}else{const rows=readStore('qayyum-notes');rows.unshift(item);writeStore('qayyum-notes',rows);toast('حُفظ السجل محلياً على هذا الجهاز.')}e.target.reset();loadLocalNotes();}
 if(e.target.id==='eventForm'){e.preventDefault();toast('تم تجهيز طلب المناسبة كنموذج. الإرسال الفعلي يحتاج حساباً وخادماً ومراجعة المالك.');e.target.reset();}
 if(e.target.id==='supportForm'){e.preventDefault();toast('هذا نموذج تجريبي؛ لم يُرسل طلب إلى الخادم.');e.target.reset();}
 if(e.target.id==='assistantForm'){e.preventDefault();if(!$('#assistantScope').value){toast('اختر نطاق المصادر أولاً.');return}toast('تم تجهيز السؤال. المساعد يحتاج ربط خدمة الذكاء الاصطناعي والمصادر.');}

 if(e.target.id==='loginForm'){e.preventDefault();try{const d=await apiRequest('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});sessionStorage.setItem('qayyum-session-token',d.token);$('#authStatus').textContent='تم تسجيل الدخول لهذه الجلسة.';toast('تم تسجيل الدخول.')}catch(err){$('#authStatus').textContent=err.message;toast(`تعذر الدخول: ${err.message}`)}}
 if(e.target.id==='registerForm'){e.preventDefault();try{const d=await apiRequest('/api/auth/register',{method:'POST',body:JSON.stringify({email:$('#registerEmail').value,password:$('#registerPassword').value,displayName:$('#registerName').value})});sessionStorage.setItem('qayyum-session-token',d.token);$('#authStatus').textContent='تم إنشاء الحساب وتسجيل الدخول.';toast('تم إنشاء الحساب.')}catch(err){toast(`تعذر إنشاء الحساب: ${err.message}`)}}
});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='book-detail'){const id=b.dataset.workId;if(!id||!API_BASE){toast('تفاصيل الكتاب تتطلب اتصال فهرس القيّوم.');return}try{const d=await apiRequest(`/api/catalog/works/${encodeURIComponent(id)}`);let panel=$('#workDetailPanel');if(!panel){panel=document.createElement('section');panel.id='workDetailPanel';panel.className='paper-card';$('#catalogResults')?.after(panel)}const w=d.work;panel.innerHTML=`<h2>بيانات الكتاب في مكتبة القيّوم</h2><div class="card-body"><h3>${escapeHtml(w.canonical_title)}</h3><p>${escapeHtml((w.authors||[]).join('، ')||'المؤلف غير محقق بعد')}</p>${w.original_title?`<p>العنوان الأصلي: ${escapeHtml(w.original_title)}</p>`:''}${w.description?`<p>${escapeHtml(w.description)}</p>`:''}<p>اللغة: ${escapeHtml(w.language_code||'غير محددة')} · حالة نسبة الكتاب: ${escapeHtml(w.attribution_status||'غير محققة')}</p><h3>الطبعات المعتمدة</h3>${d.editions.length?d.editions.map(x=>`<div class="notice-strip"><b>${escapeHtml(x.edition_title||'طبعة')}</b><p>${escapeHtml([x.editor_name&&`تحقيق: ${x.editor_name}`,x.translator_name&&`ترجمة: ${x.translator_name}`,x.publication_place,x.publication_year_text,x.volume_count&&`${x.volume_count} مجلد`].filter(Boolean).join(' · ')||'بيانات الطبعة قيد الاستكمال')}</p></div>`).join(''):'<div class="empty-state">لا توجد طبعات معتمدة لعرضها حالياً.</div>'}</div>`;panel.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){toast(`تعذر تحميل بيانات الكتاب: ${err.message}`)}}
 else if(a==='rights-info')toast('لا يُتاح تنزيل أي ملف قبل التحقق من حقوقه.');
 else if(a==='external-search')toast('سيُربط البحث الخارجي بمصادر الفهرسة مع توثيق كل سجل.');
 else if(a==='save-calendar'){toast('حُفظ اختيار العرض محلياً لهذه الجلسة.');}
 else if(a==='open-notes'||a==='open-investigation'||a==='open-citations'||a==='reading-plan'||a==='terms'){const kinds={'open-notes':'note','open-investigation':'research','open-citations':'citation','reading-plan':'research','terms':'note'};const labels={'open-notes':'دفتر المطالعة','open-investigation':'دفتر التحقيق','open-citations':'إدارة الاقتباسات','reading-plan':'خطة القراءة','terms':'المصطلحات العلمية'};if($('#noteKind'))$('#noteKind').value=kinds[a];toast(`تم فتح ${labels[a]} ضمن الدفتر.`);$('#studyWorkspace')?.scrollIntoView({behavior:'smooth'});}
 else if(a==='export-info')toast('تصدير Word وPDF سيُفعّل بعد ربط خدمة المستندات.');
 else if(a==='push-permission'){if(b.checked&&'Notification'in window){const p=await Notification.requestPermission();toast(p==='granted'?'تم السماح للمتصفح مبدئياً؛ يلزم خادم لإرسال الإشعارات.':'لم يتم منح إذن الإشعارات.')}else if(b.checked){toast('المتصفح لا يدعم إشعارات الويب هنا.')}}
 else if(a==='admin-section')toast(`قسم الإدارة «${b.dataset.section}» يحتاج جلسة مالك موثقة وصلاحيات خادم.`);
 else if(a==='report-info')toast('التقارير ستُنشأ من البيانات الفعلية بعد تشغيل قاعدة البيانات.');
 else if(a==='reader-upload'){const file=$('#readerFile')?.files?.[0];if(!file){toast('اختر ملف PDF أو EPUB أولاً.');return}if(!API_BASE||!apiToken()){toast('اضبط API وسجّل الدخول أولاً.');return}try{const form=new FormData();form.append('file',file);const result=await apiRequest('/api/files',{method:'POST',body:form});toast(`أُرسل الملف إلى الحجر للمراجعة · ${result.status}`)}catch(err){toast(`تعذر رفع الملف: ${err.message}`)}}
 else if(a==='reader-zoom-in'||a==='reader-zoom-out'){const c=$('#readerCanvas .card-body');if(c){const size=parseFloat(c.dataset.fontSize||'16')+(a==='reader-zoom-in'?1:-1);c.dataset.fontSize=String(Math.max(12,Math.min(30,size)));c.style.fontSize=size+'px';toast('تم تعديل حجم عرض النص التجريبي.')}else toast('افتح كتاباً أولاً لتفعيل التكبير.');}
 else if(a==='reader-night'){const c=$('#readerCanvas');if(c){c.classList.toggle('reader-night');toast('تم تبديل وضع القراءة.')}else toast('افتح كتاباً أولاً.');}
 else if(a==='reader-bookmark'){const pg=$('#readerPage')?.value||'1';const rows=readStore('qayyum-reader-bookmarks');rows.unshift({page:pg,at:Date.now()});writeStore('qayyum-reader-bookmarks',rows);$('#readerSavedItems').innerHTML=renderReaderSavedItems();toast(`حُفظت علامة للصفحة ${pg} على هذا المتصفح.`);}
 else if(a==='reader-note'){const note=window.prompt('اكتب ملاحظة لهذه الصفحة:');if(note){const rows=readStore('qayyum-reader-notes');rows.unshift({page:$('#readerPage')?.value||'1',note,at:Date.now()});writeStore('qayyum-reader-notes',rows);$('#readerSavedItems').innerHTML=renderReaderSavedItems();toast('حُفظت الملاحظة محلياً.')}}
 else if(a==='accessibility-save'){document.body.classList.toggle('large-text',$('#largeText')?.checked);document.body.classList.toggle('high-contrast',$('#highContrast')?.checked);document.documentElement.style.scrollBehavior=$('#reduceMotion')?.checked?'auto':'smooth';toast('تم تطبيق تفضيلات العرض على هذا الجهاز.');}
});
const extraStyle=document.createElement('style');extraStyle.textContent='.large-text{font-size:110%}.large-text .page-view{font-size:1.08em}.high-contrast{filter:contrast(1.12)}';document.head.append(extraStyle);
